/* @autogenerated */
import { Component, Inject } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { MAT_DIALOG_DATA, MatDialogModule, MatDialogRef } from '@angular/material/dialog';
import { MatButtonModule } from '@angular/material/button';
import { MatFormFieldModule } from '@angular/material/form-field';
import { MatInputModule } from '@angular/material/input';
import { MatSelectModule } from '@angular/material/select';
import { TranslocoModule } from '@jsverse/transloco';
import { BulkEditChange, BulkEditField, BulkEditOperation } from './bulk-edit.model';

interface BulkEditRow {
  enabled: boolean;
  operation: BulkEditOperation;
  value: string | number | boolean | null;
}

@Component({
  selector: 'bulk-edit-dialog',
  standalone: true,
  imports: [
    FormsModule,
    MatDialogModule,
    MatButtonModule,
    MatFormFieldModule,
    MatInputModule,
    MatSelectModule,
    TranslocoModule,
  ],
  template: `
    <h2 mat-dialog-title>{{ data.title }}</h2>
    <mat-dialog-content>
      <p>{{ data.count }} {{ data.count === 1 ? data.singular : data.plural }}</p>
      @for (field of data.fields; track field.name; let i = $index) {
        <section class="field-row">
          <label><input type="checkbox" [(ngModel)]="rows[i].enabled" /> {{ field.label }}</label>
          @if (rows[i].enabled) {
            <mat-form-field>
              <mat-label>{{ 'common.bulkEdit.operation' | transloco }}</mat-label>
              <mat-select [(ngModel)]="rows[i].operation">
                @for (operation of operations(field); track operation.value) {
                  <mat-option [value]="operation.value">{{ operation.labelKey | transloco }}</mat-option>
                }
              </mat-select>
            </mat-form-field>
            @if (requiresValue(rows[i].operation)) {
              <mat-form-field>
                <mat-label>{{ 'common.bulkEdit.value' | transloco }}</mat-label>
                @if (field.type === 'enum') {
                  <mat-select [(ngModel)]="rows[i].value">
                    @for (option of field.options ?? []; track option.value) {
                      <mat-option [value]="option.value">{{ option.label }}</mat-option>
                    }
                  </mat-select>
                } @else {
                  <input matInput [type]="field.type === 'number' ? 'number' : 'text'" [(ngModel)]="rows[i].value" />
                }
              </mat-form-field>
            }
          }
        </section>
      }
    </mat-dialog-content>
    <mat-dialog-actions align="end">
      <button mat-button mat-dialog-close>{{ data.cancel }}</button>
      <button mat-raised-button color="primary" [disabled]="!hasChanges()" (click)="submit()">
        {{ data.confirm }}
      </button>
    </mat-dialog-actions>
  `,
  styles: `
    .field-row {
      display: flex;
      align-items: center;
      gap: 1rem;
      min-height: 56px;
    }
    .field-row label {
      min-width: 9rem;
    }
    mat-form-field {
      flex: 1;
    }
  `,
})
export class BulkEditDialogComponent<T = unknown> {
  readonly rows: BulkEditRow[];

  constructor(
    @Inject(MAT_DIALOG_DATA) readonly data: BulkEditDialogData<T>,
    private readonly ref: MatDialogRef<BulkEditDialogComponent<T>, BulkEditChange[] | null>,
  ) {
    this.rows = data.fields.map((field) => ({
      enabled: false,
      operation: this.operations(field)[0].value,
      value: field.type === 'number' ? 0 : '',
    }));
  }

  operations(field: BulkEditField<T>): { value: BulkEditOperation; labelKey: string }[] {
    if (field.type === 'boolean') {
      return [
        { value: 'setTrue', labelKey: 'common.bulkEdit.operations.setTrue' },
        { value: 'setFalse', labelKey: 'common.bulkEdit.operations.setFalse' },
      ];
    }
    if (field.type === 'enum') return [{ value: 'replace', labelKey: 'common.bulkEdit.operations.setValue' }];
    if (field.type === 'relation') return [{ value: 'setNull', labelKey: 'common.bulkEdit.operations.setNull' }];
    const choices: { value: BulkEditOperation; labelKey: string }[] =
      field.type === 'number'
        ? [
            { value: 'replace', labelKey: 'common.bulkEdit.operations.replace' },
            { value: 'add', labelKey: 'common.bulkEdit.operations.add' },
            { value: 'multiply', labelKey: 'common.bulkEdit.operations.multiply' },
          ]
        : [
            { value: 'replace', labelKey: 'common.bulkEdit.operations.replace' },
            { value: 'prefix', labelKey: 'common.bulkEdit.operations.prefix' },
            { value: 'suffix', labelKey: 'common.bulkEdit.operations.suffix' },
          ];
    return field.optional ? [...choices, { value: 'clear', labelKey: 'common.bulkEdit.operations.clear' }] : choices;
  }

  requiresValue(operation: BulkEditOperation): boolean {
    return ['replace', 'prefix', 'suffix', 'add', 'multiply'].includes(operation);
  }

  hasChanges(): boolean {
    return this.rows.some((row) => row.enabled && (!this.requiresValue(row.operation) || row.value !== ''));
  }

  submit(): void {
    const changes = this.data.fields.flatMap((field, index) => {
      const row = this.rows[index];
      if (!row.enabled || (this.requiresValue(row.operation) && row.value === '')) return [];
      const value = row.operation === 'setTrue' ? true : row.operation === 'setFalse' ? false : row.value;
      return [
        {
          field: field.name,
          operation: row.operation,
          value: row.operation === 'setNull' || row.operation === 'clear' ? null : value,
        },
      ];
    });
    this.ref.close(changes);
  }
}

export interface BulkEditDialogData<T> {
  readonly title: string;
  readonly count: number;
  readonly singular: string;
  readonly plural: string;
  readonly confirm: string;
  readonly cancel: string;
  readonly fields: readonly BulkEditField<T>[];
}
